package routing;

/**
 * One customer order as the warehouse receives it. Given: do not edit this file.
 *
 * @param channel  where the order came from, such as "web" or "phone"
 * @param number   the order number, unique within its channel
 * @param sku      the product to pick, such as "mug"
 * @param quantity how many units to pick
 * @param station  the packing station that packs it, such as "B2"
 */
public record Order(String channel, int number, String sku, int quantity, String station) {

    /** The key the registry stores this order under. */
    public OrderKey key() {
        return new OrderKey(channel, number);
    }
}
